package vn.somehouse;
import static vn.somehouse.ApiTypes.*;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import java.util.*;import java.net.URI;
@Service public class SiteService {
 final JdbcTemplate db;final CatalogService catalog;SiteService(JdbcTemplate d,CatalogService c){db=d;catalog=c;}
 public Map<String,Object> settings(){var r=db.queryForList("SELECT data_json,version FROM site_settings WHERE id=1");if(r.isEmpty())throw new ApiException(org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE,"NOT_INITIALIZED","Chưa cấu hình website.");return Map.of("data",catalog.read((String)r.getFirst().get("data_json")),"version",r.getFirst().get("version"));}
 public void settings(SettingInput in){JsonNode n=in.data();if(!n.isObject())throw ApiException.invalid("Cấu hình phải là JSON object.");Set<String> keys=Set.of("brandName","phone","phoneHref","address","authorName","logoUrl","avatarUrl","socials");n.fieldNames().forEachRemaining(k->{if(!keys.contains(k))throw ApiException.invalid("Trường cấu hình không hợp lệ.");});for(String k:List.of("brandName","phone","address","authorName","logoUrl","avatarUrl"))if(!n.path(k).isTextual()||n.path(k).asText().isBlank()||n.path(k).asText().length()>500)throw ApiException.invalid("Thiếu hoặc sai cấu hình: "+k);String phone=n.path("phone").asText().replaceAll("[^+0-9]","");if(!phone.matches("\\+?[0-9]{9,15}"))throw ApiException.invalid("Số điện thoại không hợp lệ.");((ObjectNode)n).put("phoneHref","tel:"+(phone.startsWith("0")?"+84"+phone.substring(1):phone));CatalogService.asset(n.path("logoUrl").asText());CatalogService.asset(n.path("avatarUrl").asText());if(!n.path("socials").isObject())throw ApiException.invalid("Cấu hình mạng xã hội không hợp lệ.");for(String k:List.of("facebook","zalo","youtube","tiktok")){var u=n.path("socials").get(k);if(u!=null&&!u.isNull()&&!u.asText().isBlank()){URI uri=URI.create(u.asText());if(!u.isTextual()||u.asText().length()>2000||!"https".equalsIgnoreCase(uri.getScheme())||uri.getHost()==null)throw ApiException.invalid("Liên kết mạng xã hội cần HTTPS.");}}if(db.update("UPDATE site_settings SET data_json=?,version=version+1 WHERE id=1 AND version=?",catalog.write(n),in.version())==0)throw ApiException.conflict();}
 public LeadReceipt lead(LeadInput in,String key){if(key==null||!key.matches("[A-Za-z0-9_-]{16,80}"))throw ApiException.invalid("Thiếu Idempotency-Key hợp lệ.");var old=db.queryForList("SELECT reference FROM leads WHERE idempotency_key=?",String.class,key);if(!old.isEmpty())return new LeadReceipt(old.getFirst(),"Đã tiếp nhận thông tin.");if(in.propertySlug()!=null&&!in.propertySlug().isBlank())catalog.detail("PROPERTY",in.propertySlug(),"vi");String ref=UUID.randomUUID().toString();try{db.update("INSERT INTO leads(reference,idempotency_key,name,phone,email,purpose,message,property_slug) VALUES(?,?,?,?,?,?,?,?)",ref,key,in.name().trim(),in.phone().trim(),CatalogService.str(in.email()),in.purpose(),in.message().trim(),in.propertySlug());}catch(DuplicateKeyException e){return new LeadReceipt(db.queryForObject("SELECT reference FROM leads WHERE idempotency_key=?",String.class,key),"Đã tiếp nhận thông tin.");}return new LeadReceipt(ref,"Đã tiếp nhận thông tin. Somehouse sẽ trao đổi lại với bạn.");}
 public Page<Map<String,Object>> leads(Map<String,String> q){int page=CatalogService.integer(q,"page",0,0,100000),size=CatalogService.integer(q,"size",20,1,50);String status=q.get("status"),where="";var args=new ArrayList<Object>();if(status!=null&&!status.isBlank()){if(!Set.of("NEW","CONTACTED","CLOSED").contains(status))throw ApiException.invalid("Trạng thái không hợp lệ.");where=" WHERE status=?";args.add(status);}long total=Objects.requireNonNull(db.queryForObject("SELECT COUNT_BIG(*) FROM leads"+where,Long.class,args.toArray()));args.add(page*size);args.add(size);return new Page<>(db.queryForList("SELECT id,reference,name,phone,email,purpose,message,property_slug,status,version,created_at FROM leads"+where+" ORDER BY created_at DESC,id DESC OFFSET ? ROWS FETCH NEXT ? ROWS ONLY",args.toArray()),page,size,total,(int)Math.ceil((double)total/size));}
 public void status(long id,LeadStatus s){if(db.update("UPDATE leads SET status=?,version=version+1 WHERE id=? AND version=?",s.status(),id,s.version())==0)throw ApiException.conflict();}
}
